 airplane=new THREE.Group();const piece=(x,y,z,w,h,d,color)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshLambertMaterial({color}));m.position.set(x,y,z);airplane.add(m);};AIRCRAFT_PARTS.forEach((part,i)=>piece(...part,['#e8e6d7','#658e99','#b8d0c8','#5d826b','#b8d0c8','#6e8a8a','#6e8a8a','#263b3b','#263b3b','#263b3b'][i]));decorateAircraft(airplane);airplane.position.set(edmontonParking.x,30,edmontonParking.z);airplane.rotation.y=Math.PI;addToDistrict(airplane,'edmonton');
 // Toronto is a separate district across the water, not another tower in the forest.
 surfaceQuad([[3619,0,-880],[3619,0,880],[5381,0,880],[5381,0,-880]],'#a6aba0',[0,1,0]);surfaceQuad([[4404,.1,-880],[4404,.1,880],[4596,.1,880],[4596,.1,-880]],'#536165',[0,1,0]);
 block(2700,-22,0,1900,6,3200,'#4b8997');td(4500,-300);
 buildTorontoAirstrip();buildJourneyPaths();experienceScenes=createExperienceScenes({THREE,block,addToDistrict,roomOrigins,wallPoster,chapters,boxGeometry,registerLight});for(const id of Object.keys(roomOrigins))experienceScenes.buildRoom(id);playerAvatar=experienceScenes.createExplorer();playerAvatar.group.scale.setScalar(.78);buildFlightLabels();buildTrail();
