function setJourney(title,description){journeyHUD.hidden=false;setHud('journey-stage',title);setHud('journey-description',description);for(const b of document.querySelectorAll('[data-journey]'))b.classList.toggle('complete',tour?.state.active?tour.state.finished.includes(b.dataset.journey):entered.has(b.dataset.journey));}
