function showChapter(id){const c=chapters[id];roomCard.innerHTML=`<span class="eyebrow">${c.eyebrow}</span><h2>${c.title}</h2><button class="room-art" id="open-room-art" aria-label="View full ${c.name} illustration"><img src="../assets/${c.image}?v=7" width="1536" height="1024" alt="Voxel illustration of ${c.name}" decoding="async"><span>View full illustration ↗</span></button><p class="room-role">${c.role}</p>${c.paragraphs.map(p=>`<p>${p}</p>`).join('')}${id==='university'?'<p class="scene-note">The 60-seat lab is an illustrated teaching scene.</p>':''}<div class="room-actions"><button id="room-next">${c.next}</button><button id="room-exit">${id==='td'?'Lift down to the concourse':'Back outside'}</button></div>`;roomCard.hidden=false;const story=document.querySelector('#story-toggle');story.hidden=false;story.textContent='Hide story';document.querySelector('#open-room-art').onclick=()=>{clearMotion();const viewer=document.querySelector('#art-viewer');viewer.querySelector('img').src='../assets/'+c.image+'?v=7';viewer.querySelector('img').alt='Voxel illustration of '+c.name;viewer.showModal();};document.querySelector('#room-exit').onclick=()=>{if(tour?.state.active&&['home','university','td','concourse'].includes(room))tour.finishChapter();else exitRoom();};document.querySelector('#room-next').onclick=()=>{if(tour?.state.active){id==='concourse'?tour.rideTo(21):tour.finishChapter();return;}if(id==='home'||id==='university'||id==='concourse')id==='concourse'?enterLift(0):exitRoom();else if(id==='td')enterLift(21);};}

function enterBuilding(id,options={}){if(flight||elevator||carTrip)return;if(tour?.state.active&&tour.state.paused)tour.stop();if(id==='td'&&!options.fromLift)id='concourse';if(!active){switchView();if(!active)return;}clearMotion();room=id;locationZone='interior';const o=roomOrigins[id],l=ROOM_LAYOUT[id];position.x=o.x+l.spawn.x;position.z=o.z+l.spawn.z;yaw=l.spawn.yaw;pitch=l.spawn.pitch;entered.add(id);loadRoomArt(id);closeRoomPanel();showChapter(id);trailKey='';setJourney(chapters[id].eyebrow,id==='td'?'Floor 21: Anhad is at his desk. Stay for the coffee break.':id==='concourse'?'Follow the glow to the lift bank, then select floor 21.':id==='university'?'A 60-seat computer lab. Follow the glowing aisle to Anhad teaching.':'Meet Anhad at his workstation. You can hide this story to explore the room.');}
function exitRoom(){if(flight||elevator||carTrip)return;if(room==='td'){enterLift(21);return;}if(room==='lift'){leaveLift();return;}const id=room;if(!id)return;travelTo(id==='concourse'?'td':id);const d=id==='home'?home:id==='university'?university:tdTerrace;placeSafely(d.x,d.z+160);portalCooldown=time+.45;if(id==='home'){routeTarget='university';setJourney('NEXT / WALK TO CAMPUS','A continuous glowing path connects home to the university. Follow it to the computer lab.');}if(id==='university'){routeTarget='pickup';setJourney('NEXT / CAMPUS CAR PICKUP','Walk across the main quad to the amber pickup. Anhad will drive you to Edmonton Airport.');}if(id==='concourse'&&entered.has('td')){routeTarget='return-flight';setJourney('NEXT / TORONTO AIRSTRIP','Follow the cyan trail to your return flight, or use the airstrip shortcut.');}trailKey='';}
function enterLift(floor=0){if(flight||elevator||carTrip)return;clearMotion();room='lift';locationZone='interior';elevatorFloor=floor;const o=roomOrigins.lift;position.x=o.x;position.z=o.z+55;yaw=0;pitch=.04;closeRoomPanel();const panel=document.querySelector('#lift-panel');panel.hidden=false;document.querySelector('#lift-exit').disabled=false;document.querySelector('#lift-up').disabled=floor===21;document.querySelector('#lift-down').disabled=floor===0;setHud('lift-floor',floor===0?'G':String(floor));setHud('lift-status',floor===0?'Choose floor 21 to visit the office.':'Choose G to return to the concourse.');setJourney('TD TERRACE / LIFT',floor===0?'Next stop: floor 21, Software Engineering.':'Return to the concourse, then follow the trail to the airstrip.');trailKey='';}
function setTransit(value){document.querySelector('#tour-toggle').disabled=value&&!tour?.state.active;for(const b of document.querySelectorAll('[data-station],[data-journey],#experience-portal,#view-toggle,#map-toggle,#return-airstrip,#walk-toggle,#story-toggle'))b.disabled=value;}
function rideLift(to){if(room!=='lift'||elevator||to===elevatorFloor)return;clearMotion();setTransit(true);document.body.classList.add('in-lift');elevator={start:time,duration:reduced?1:4,from:elevatorFloor,to};document.querySelector('#lift-up').disabled=true;document.querySelector('#lift-down').disabled=true;document.querySelector('#lift-exit').disabled=true;setHud('lift-status',to===21?'Going up · Software Engineering':'Going down · Concourse');}
function liftFrame(){const t=Math.min(1,(time-elevator.start)/elevator.duration),floor=Math.round(THREE.MathUtils.lerp(elevator.from,elevator.to,t));setHud('lift-floor',floor===0?'G':String(floor));const o=roomOrigins.lift;camera.position.set(o.x,64+(reduced?0:Math.sin(t*Math.PI)*.6),o.z+55);camera.rotation.set(.04,0,0,'YXZ');if(t===1){const to=elevator.to;elevator=null;setTransit(false);document.body.classList.remove('in-lift');elevatorFloor=to;document.querySelector('#lift-panel').hidden=true;document.querySelector('#lift-exit').disabled=false;to===21?enterBuilding('td',{fromLift:true}):enterBuilding('concourse');}}
function leaveLift(){if(elevator)return;document.body.classList.remove('in-lift');document.querySelector('#lift-panel').hidden=true;elevatorFloor===21?enterBuilding('td',{fromLift:true}):enterBuilding('concourse');}
function startAirportTransfer(back=false){if(flight||elevator||carTrip)return;if(!active){switchView();if(!active)return;}clearMotion();room=null;locationZone='edmonton';closeRoomPanel();world.dialog.close();transfer.start(back,reduced);carTrip={back,cameraReady:false};setTransit(true);document.body.classList.add('in-car');document.querySelector('#drive-overlay').hidden=false;setHud('drive-title',back?'Airport → University of Alberta':'Campus → Edmonton Airport');setHud('drive-caption',back?'One last drive home, then back to the main quad.':'Anhad is at the wheel. Follow the amber road past the neighbourhood.');}
function driveFrame(dt){const paused=tour?.state.active&&tour.state.paused,sample=transfer.update(dt,paused);position.x=sample.position.x;position.z=sample.position.z;if(playerAvatar)playerAvatar.group.visible=false;const goal=cameraGoal.set(position.x+Math.sin(sample.heading)*230,125,position.z+Math.cos(sample.heading)*230),target=cameraTarget.set(position.x,39,position.z);if(!carTrip.cameraReady){camera.position.copy(goal);carTrip.cameraReady=true;}else camera.position.lerp(goal,paused?0:1-Math.exp(-4*dt));camera.lookAt(target);document.querySelector('#drive-progress').value=sample.progress;if(sample.done){const back=carTrip.back;carTrip=null;transfer.finish();setTransit(false);document.body.classList.remove('in-car');document.querySelector('#drive-overlay').hidden=true;clearMotion();locationZone='edmonton';placeSafely(back?500:-2100,back?-150:-480);yaw=0;pitch=.04;routeTarget=back?'quad-return':'flight';setJourney(back?'WELCOME BACK / MAIN QUAD':'YEG / DEPARTURES',back?'The quad is just ahead. Thanks for taking the scenic route.':'Follow the blue line through check-in and security to Gate A1.');}}
function takeFlight(direction){if(flight||elevator||carTrip)return;if(!active)switchView();const back=direction==='return'||(direction!=='outbound'&&(locationZone==='toronto'||['td','concourse','lift'].includes(room)));clearMotion();room=null;closeRoomPanel();world.dialog.close();const from=back?torontoAirport:airport,to=back?airport:torontoAirport,fromParking=back?torontoParking:edmontonParking,toParking=back?arrivalParking.edmonton:arrivalParking.toronto,plan=createFlightPlan({from,to,fromParking,toParking,reduced});camera.fov=82;camera.updateProjectionMatrix();setTransit(true);flight={start:time,duration:plan.duration,back,from,to,fromParking,toParking,plan,plane:back?returnAirplane:airplane,phase:'TAXI TO RUNWAY',cameraReady:false,cameraTarget:new THREE.Vector3(),wheels:[],fans:[]};flight.plane.traverse(o=>{if(o.name==='landing-wheel')flight.wheels.push(o);if(o.name==='engine-fan')flight.fans.push(o);});flight.plane.position.set(fromParking.x,30,fromParking.z);locationZone='flight';document.body.classList.add('in-flight');document.querySelector('#flight-overlay').hidden=false;setHud('flight-origin',back?'Toronto':'Edmonton');setHud('flight-destination',back?'Edmonton':'Toronto');setJourney('RUNWAY JOURNEY',back?'Returning to Edmonton.':'Next stop: Toronto and TD Terrace.');scene.fog.near=4500;scene.fog.far=15000;trailKey='';}
function flightFrame(dt){
 const f=flight,sample=f.plan.sample(time-f.start),p=sample.position,paused=tour?.state.active&&tour.state.paused,blend=paused?0:1-Math.exp(-5*dt);f.phase=sample.phase;f.sample=sample;f.plane.position.set(p.x,p.y,p.z);
 if(!f.cameraReady){f.plane.rotation.set(sample.pitch,sample.heading,sample.bank,'YXZ');}else{f.plane.rotation.y=wrapAngle(f.plane.rotation.y+wrapAngle(sample.heading-f.plane.rotation.y)*blend);f.plane.rotation.x=THREE.MathUtils.lerp(f.plane.rotation.x,sample.pitch,blend);f.plane.rotation.z=THREE.MathUtils.lerp(f.plane.rotation.z,sample.bank,blend);}
 const direction=f.back?-1:1,aerial=THREE.MathUtils.smoothstep(p.y,120,1100),goal=cameraGoal.set(p.x-direction*275,p.y+155+95*aerial,p.z+365),target=cameraTarget.set(p.x-direction*80,p.y+18-318*aerial,p.z-90);const animationDt=paused?0:dt;f.wheelAngle=(f.wheelAngle||0)+(sample.grounded?sample.speed*animationDt/5:0);for(const wheel of f.wheels)wheel.rotation.x=f.wheelAngle;for(const fan of f.fans)fan.rotation.z+=animationDt*(sample.grounded?12:35);
 if(!f.cameraReady){camera.position.copy(goal);f.cameraTarget.copy(target);f.cameraReady=true;}else{const follow=paused?0:1-Math.exp(-4*dt);camera.position.lerp(goal,follow);f.cameraTarget.lerp(target,follow);}camera.lookAt(f.cameraTarget);
 document.querySelector('#flight-progress').style.width=`${sample.progress*100}%`;setHud('flight-status',sample.phase);setHud('flight-location',sample.phase==='CRUISE'?'Mountain corridor · snowy ridges, forests and lakes below':sample.phase==='FINAL APPROACH'||sample.phase==='FLARE / TOUCHDOWN'?`Lined up with ${f.back?'Edmonton':'Toronto'} runway 36`:sample.phase==='CLIMB'&&!f.back?'Walterdale Bridge · river valley · Edmonton skyline':sample.grounded?'Follow the runway markings and edge lights':`Climbing towards ${f.back?'Edmonton':'Toronto'}`);
 if(sample.done){flight=null;setTransit(false);document.body.classList.remove('in-flight');document.querySelector('#flight-overlay').hidden=true;scene.fog.near=1600;scene.fog.far=6500;travelTo(f.back?'edmonton-airport':'td');placeSafely(f.back?airport.arrival.x:torontoAirport.arrival.x,f.back?airport.arrival.z:torontoAirport.arrival.z);yaw=Math.PI;pitch=.04;routeTarget=f.back?'campus-return':'td';setJourney(f.back?'WELCOME BACK / EDMONTON':'LANDED / TORONTO ARRIVALS',f.back?'The aircraft has taxied clear of the runway. Follow the glow back to campus.':'Touchdown, rollout, then arrivals. Follow the glowing footpath to TD Terrace.');trailKey='';}
}
function buildFlightLabels(){for(const [text,x,z]of [['EDMONTON / CAMPUS',750,-50],['YEG / EDMONTON AIRPORT',airport.x,airport.z],['WALTERDALE BRIDGE',370,-1740],['DOWNTOWN EDMONTON',260,-2570],['TORONTO / UNION STATION',4750,-430],['TORONTO / TD TERRACE',4500,-300],['TORONTO / RUNWAY 36',5050,200]]){const c=document.createElement('canvas');c.width=1024;c.height=128;const g=c.getContext('2d');g.fillStyle='#142d27e6';g.fillRect(0,0,1024,128);g.fillStyle='#daf2b7';g.font='bold 43px monospace';g.textAlign='center';g.fillText(text,512,79);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;const mesh=new THREE.Sprite(new THREE.SpriteMaterial({map:t,depthTest:false,transparent:true,sizeAttenuation:false}));mesh.position.set(x,230,z);mesh.scale.set(.32,.04,1);addToDistrict(mesh,'flight-labels');}}
