function buildTrail(){trailMesh=new THREE.InstancedMesh(new THREE.BoxGeometry(8,.7,17),new THREE.MeshBasicMaterial({color:'#b4f9cc',transparent:true,opacity:.95,toneMapped:false}),240);trailHalo=new THREE.InstancedMesh(new THREE.BoxGeometry(15,.3,25),new THREE.MeshBasicMaterial({color:'#6be6dc',transparent:true,opacity:.22,toneMapped:false,depthWrite:false}),240);trailTip=new THREE.Mesh(new THREE.OctahedronGeometry(7),new THREE.MeshBasicMaterial({color:'#c7ffbc',toneMapped:false}));scene.add(trailMesh,trailHalo,trailTip);}
let activeTrailPoints=[],tourRoute=null,tourPath=null;
function routePoints(id){const [kind,name]=id.split(':');if(kind==='room'||kind==='reverse'||kind==='exit'){const o=roomOrigins[name],points=ROOM_ROUTES[name].map(([x,z])=>[o.x+x,o.z+z]);if(kind==='exit')return [...points.reverse(),[o.x,o.z+ROOM_LAYOUT[name].spawn.z],[o.x,o.z+ROOM_LAYOUT[name].exitZ]];return kind==='reverse'?points.reverse():points;}if(id.startsWith('station-')){const s=world.stations[Number(id.slice(8))];return [[position.x,position.z],[s.x*S,s.y*S+110]];}return EXPERIENCE_ROUTES[id]||EXPERIENCE_ROUTES.portal;}
function getRoute(id){const joined=joinRoute(position,routePoints(id));if(joined.length<2)return joined;const result=[joined[0]];for(let i=1;i<joined.length;i++){const connector=safeConnector(result.at(-1),joined[i],isBlocked);if(!connector.length)return [];result.push(...connector.slice(1));}return result;}
function currentRoute(){if(tour?.state.active&&tourRoute&&(room?tourRoute.endsWith(':'+room):!tourRoute.includes(':')))return tourRoute;return room?'room:'+room:routeTarget;}
