const guideSeen=new Set();let dialogueGuide=null;
const GUIDE_STORIES={
 home:{intro:'Hey, welcome to my home base! Space Copy was a remote internship, so this is my imagined place to build, ask questions and think about software with an aerospace horizon.',work:'At Space Copy, I worked remotely on software in an aerospace-focused environment, helping translate technical needs into practical development work. This mansion is a playful home-workspace scene, rather than a company office.',lesson:'What I value in remote work is making the next step clear: ask a focused question, share useful context, and leave notes another person can act on. That habit helps remote teammates move forward together, even when we are working in different places.'},
 university:{intro:'Welcome to the lab! I’m Anhad. My favourite moment in teaching is when a confusing problem finally clicks. Let’s try one small example before making the problem bigger.',work:'At the University of Alberta, I study Computing Science and help teach Python and algorithmic problem solving. I review code, discuss edge cases and mentor students. I previously served as Head TA for CMPUT 174.',lesson:'Try explaining an algorithm out loud. If a step is hard to explain, that is often where I start asking better questions. A tiny test case can reveal more than another page of code.'},
 td:{intro:'Welcome to floor 21! This is my Toronto chapter: a workstation, a coffee, and a backend problem to untangle. Come around the desk and I’ll tell you what I worked on.',work:'At TD, I built Python-driven automation, worked with Jenkins and Git-based CI workflows, and investigated backend issues using APIs, SQL and logs. I collaborated with engineers through Agile delivery cycles.',lesson:'The part I enjoy is connecting the evidence: a log, an API trace and a SQL query can explain different pieces of the same issue. Once it makes sense, I look for a repeatable workflow the team can use.'}
};
function showGuide(id,topic='intro'){if(!GUIDE_STORIES[id])return;dialogueGuide=id;guideSeen.add(id);document.querySelector('#npc-name').textContent='ANHAD · '+chapters[id].role;document.querySelector('#npc-message').textContent=GUIDE_STORIES[id][topic];document.querySelector('#guide-topics').hidden=false;document.querySelectorAll('[data-guide-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.guideTopic===topic)));document.querySelector('#npc-done').textContent=tour?.state.active?'Done · next experience →':'Back to exploring';document.querySelector('#npc-dialogue').hidden=false;window.speechSynthesis?.cancel();}
function updateGuideProximity(){if(!room||!GUIDE_STORIES[room]||guideSeen.has(room)||!document.querySelector('#npc-dialogue').hidden)return;if(experienceScenes.nearbyGuide(position.x,position.z,room))showGuide(room);}
for(const b of document.querySelectorAll('[data-guide-topic]'))b.onclick=()=>{interactionIntent();showGuide(dialogueGuide,b.dataset.guideTopic);};
document.querySelector('#dialogue-listen').onclick=()=>{interactionIntent();if(!window.speechSynthesis){world.notify('Spoken narration is unavailable here. The full story is shown in the caption.');return;}window.speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(document.querySelector('#npc-message').textContent);speech.rate=.96;window.speechSynthesis.speak(speech);};
function dismissConversation(){document.querySelector('#npc-dialogue').hidden=true;dialogueGuide=null;window.speechSynthesis?.cancel();pointerLook.reset();}
function finishConversation(){const owner=dialogueGuide;dismissConversation();if(tour?.state.active){if(owner&&['home','university','td'].includes(room))tour.finishChapter();else tour.resumeInteraction();}}
function aimTour(x,z,dt){const focus=tourFocus||[x,z],distance=Math.hypot(position.x-focus[0],position.z-focus[1]);if(distance>20){const target=Math.atan2(position.x-focus[0],position.z-focus[1]);yaw=turnTowards(yaw,target,dt,.8);}pitch=THREE.MathUtils.damp(pitch,.02,3,dt);}
tour=createGuidedTour({
 clear:clearMotion,dismiss:dismissConversation,travel:travelTo,exit:exitRoom,enter:enterBuilding,enterLift,rideLift,fly:takeFlight,drive:startAirportTransfer,move,aim:aimTour,route:id=>{tourRoute=id;trailKey='';const points=getRoute(id);tourPath=points;tourFocus=['flight','td','return-flight','campus-return'].includes(id)?null:points.at(-1)||null;if(id==='room:home')tourFocus=[roomOrigins.home.x-85,roomOrigins.home.z-20];if(id==='room:university')tourFocus=[roomOrigins.university.x,roomOrigins.university.z-325];if(id==='room:td')tourFocus=[roomOrigins.td.x-155,roomOrigins.td.z-100];return points;},speak:showGuide,notify:world.notify,
 state:()=>({room,position:{...position},flying:!!flight,riding:!!elevator,driving:!!carTrip,atGate:Math.hypot(position.x-(locationZone==='toronto'?torontoParking.x:edmontonParking.x),position.z-(locationZone==='toronto'?torontoParking.z:edmontonParking.z))<190}),
 ui:state=>{if(state.active)gameFlow?.markRunning();if(state.completed)gameFlow?.showFinish(true);if(!state.active||state.index===0)tourRoute=null;const b=document.querySelector('#tour-toggle');b.textContent=state.active?(state.paused?'▶ Resume tour':'Ⅱ Pause tour'):state.completed?'↻ Replay tour':'▶ Autoplay tour';b.setAttribute('aria-pressed',String(state.active&&!state.paused));document.querySelector('#tour-status').hidden=!state.active&&!state.completed;document.querySelector('#tour-caption').textContent=(state.paused?(state.pauseReason==='interaction'?'READING · Done continues the journey. ':'PAUSED · '):'')+state.label;document.querySelector('#tour-next').hidden=!state.active;document.querySelector('#tour-next').disabled=!!flight||!!elevator||!!carTrip||room==='lift';document.querySelector('#chapter-count').textContent=state.finished.length+' / 3 CHAPTERS';document.querySelectorAll('[data-journey]').forEach(n=>{if(['home','university','td'].includes(n.dataset.journey)){n.classList.toggle('complete',state.finished.includes(n.dataset.journey));n.classList.toggle('current',state.chapter===n.dataset.journey);}});document.querySelector('#tour-stop').hidden=!state.active;document.querySelector('#tour-end').hidden=!state.active;b.disabled=(!!flight||!!elevator||!!carTrip)&&!state.active;document.querySelector('#tour-progress').value=state.completed?state.total:state.index;document.querySelector('#tour-progress').max=state.total;document.body.classList.toggle('tour-active',state.active);document.body.classList.toggle('tour-paused',state.paused);trailKey='';}
});
