window.firstPerson={switchView,get active(){return active;},get ready(){return initialized;},get position(){return {...position};},get camera(){return camera;},get viewMode(){return active?cameraMode:'map';},get player(){return playerAvatar?.group;},get playerHeight(){return 97*.78;},get crystalPositions(){return crystalMeshes.map(m=>m.position.toArray());},get landscape(){return landscape;},get cityScenery(){return cityScenery;},get collisionBoxes(){return colliders.map(c=>({...c}));},get sceneryBoxes(){return [...batches.values()].flatMap(b=>b.list).concat(landscape?.obstacles||[]);},get auditAirspace(){return createAirspaceAudit([...batches.values()].flatMap(b=>b.list).concat(landscape?.obstacles||[]));},get citizens(){return cityLife?.citizens;},get visibleWorld(){return Object.fromEntries([...districtGroups].map(([id,g])=>[id,g.visible]));},get near(){return near;},get renderer(){return renderer;},get scene(){return scene;},teleport(x,z){position.x=x;position.z=z;},get lift(){return lift;},look,showMap,visitStation,startJourney,enterBuilding,exitRoom,takeFlight,travelTo,get driving(){return !!carTrip;},get transfer(){return transfer;},startAirportTransfer,get airports(){return AIRPORTS;},get neighbourhood(){return neighbourhood;},get gameFlow(){return gameFlow;},get room(){return room;},get zone(){return locationZone;},get flying(){return !!flight;},get entered(){return [...entered];},get door(){return currentDoor();},get trackVelocity(){return {...trackVelocity};},get cruising(){return cruise;},get frameAverage(){return frameAverage;},enterLift,rideLift,leaveLift,get ridingLift(){return !!elevator;},get elevatorFloor(){return elevatorFloor;},get studentCount(){return experienceScenes?.studentCount||0;},get actors(){return experienceScenes?.actors;},get trailVisible(){return trailOn&&trailMesh?.visible;},get inWater(){return waterBlocked(position.x,position.z);},get npcCounts(){return {students:experienceScenes.npcs.filter(n=>n.room==='university').length,colleagues:experienceScenes.npcs.filter(n=>n.room==='td').length};},get npcs(){return experienceScenes.npcs;},get workstations(){return experienceScenes.workstations;},get nightLights(){return {...nightLighting?.stats,facadeCounts:Object.fromEntries(cityScenery?.buildingLights||[]),fixtures:lightFixtures.length,active:poolLights.filter(l=>l.intensity>0).length,glow:nightObjects.filter(o=>o.material?.isShaderMaterial&&o.visible).length};},get guides(){return experienceScenes.guides;},get trailPoints(){return activeTrailPoints.map(p=>[...p]);},get tour(){return tour;},get aircraft(){return {edmonton:airplane.position.toArray(),toronto:returnAirplane.position.toArray(),edmontonParking,torontoParking,flight:flight?{back:flight.back,phase:flight.phase,sample:flight.sample,elapsed:time-flight.start,duration:flight.duration,position:flight.plane.position.toArray(),target:flight.to}:null};},get landmarks(){return buildings.landmarks.map(a=>({...a}));}};
