gameFlow=createGameFlow({start({autoplay,view,chapter}){if(view==='map'){active=false;window.fppActive=false;document.querySelector('#world').hidden=false;world.refresh();return true;}cameraMode=view;if(!active)switchView();if(!active)return false;if(autoplay){if(['home','university','td'].includes(chapter))tour.selectChapter(chapter);else tour.start();}else if(new URLSearchParams(location.search).get('journey')==='experience')startJourney();return true;},pause(){window.speechSynthesis?.cancel();const running=tour.state.active&&!tour.state.paused;if(running)tour.pause('menu');clearMotion();return running;},continue(resume){if(resume)tour.resume();previous=performance.now();},replay(){document.querySelector('#reset').click();tour.start();}});
